// Research is not free and not always useful. A product launch from a brief that already
// contains the facts needs none; a market-commentary piece needs it badly.
const b = $json.payload.brief;
const hasFacts = (b.offer?.proof || []).length > 0 && (b.message?.key_claims || []).every(c => c.substantiation);
const needsMarket = ['awareness', 'demand_gen', 'brand'].includes(b.objective) || (b.message?.angle || '').match(/trend|market|compare|versus|industry/i);
return [{ json: { research: !hasFacts || !!needsMarket, query: `${b.offer?.name} ${b.message?.angle} ${b.audience?.description}`.slice(0, 300) } }];

// One long-form anchor if any slot needs it; everything else shards from that anchor so
// the whole campaign says one consistent thing.
const b = $('Envelope In').first().json.payload.brief;
const LONG = new Set(['blog', 'email', 'product_listing']);
const slots = b.channels || [];
const anchorSlot = slots.find(s => LONG.has(s.channel)) || null;
return [{ json: {
  anchor: anchorSlot,
  shards: slots.filter(s => s !== anchorSlot),
  locales: b.constraints?.locales || ['en-US'],
  total_slots: slots.length
} }];
